/** Only files generated by this adapter are deletable. A URI-prefix check alone
 * admits ../ and encoded traversal when the native filesystem resolves a URI. */
export function isManagedPhotoRef(ref: string, rootUri: string): boolean {
  const prefix = rootUri.replace(/\/$/, '') + '/';
  return ref.startsWith(prefix) && /^[A-Za-z0-9_-]{1,128}\/[A-Za-z0-9_-]+\.(jpg|jpeg|png|webp|heic|heif|gif)$/.test(ref.slice(prefix.length));
}
